WITNESS = {
 '1': 2, '2': 3, '3': 7, '4': 5, '5': 11, '6': 7, '7': 29, '8': 17, '9': 19, '10': 11,
 '11': 23, '12': 13, '13': 53, '14': 29, '15': 31, '16': 17, '17': 103, '18': 19, '19': 191, '20': 41,
 '21': 43, '22': 23, '23': 47, '24': 73, '25': 101, '26': 53, '27': 109, '28': 29, '29': 59, '30': 31
}

def is_prime(k):
    if k < 2:
        return False
    i = 2
    while i * i <= k:
        if k % i == 0:
            return False
        i += 1
    return True

def verify():
    if set(WITNESS.keys()) != {str(i) for i in range(1, 31)}:
        return False
    for n in range(1, 31):
        p = WITNESS[str(n)]
        if not isinstance(p, int) or p < 2:
            return False
        if not is_prime(p):
            return False
        if (p - 1) % n != 0:
            return False
        x = 1 + n
        while x < p:
            if is_prime(x):
                return False
            x += n
    return True

RESULT = verify()
